INSERT INTO `user19` VALUES ('  `name` varchar(60) DEFAULT \'\' COMMENT \'活动名称\',');
INSERT INTO `user19` VALUES ('  `status` tinyint NOT NULL DEFAULT \'0\' COMMENT \'活动状态\',');
INSERT INTO `user19` VALUES ('  `main_image` varchar(100) DEFAULT \'\' COMMENT \'活动图片地址\',');
INSERT INTO `user19` VALUES ('  `start_time` datetime DEFAULT NULL COMMENT \'开始时间\',');
INSERT INTO `user19` VALUES ('  `end_time` datetime DEFAULT NULL COMMENT \'结束时间\',');
INSERT INTO `user19` VALUES ('  PRIMARY KEY (`id`) USING BTREE');
