INSERT INTO `user19` VALUES ('DROP TABLE IF EXISTS `product`;');
INSERT INTO `user19` VALUES ('CREATE TABLE `product` (');
INSERT INTO `user19` VALUES ('  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT \'主键\',');
INSERT INTO `user19` VALUES ('  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'创建时间\',');
INSERT INTO `user19` VALUES ('  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',');
INSERT INTO `user19` VALUES ('  `create_user` bigint NOT NULL DEFAULT \'0\' COMMENT \'创建人\',');
INSERT INTO `user19` VALUES ('  `update_user` bigint NOT NULL DEFAULT \'0\' COMMENT \'更新人\',');
INSERT INTO `user19` VALUES ('  `delete_flag` tinyint NOT NULL DEFAULT \'0\' COMMENT \'删除标志\',');
INSERT INTO `user19` VALUES ('  `product_id` bigint DEFAULT \'0\' COMMENT \'商品id\',');
INSERT INTO `user19` VALUES ('  `category_id` bigint DEFAULT \'0\' COMMENT \'品类id\',');
INSERT INTO `user19` VALUES ('  `name` varchar(60) DEFAULT \'\' COMMENT \'商品名称\',');
INSERT INTO `user19` VALUES ('  `sub_title` varchar(100) DEFAULT \'\' COMMENT \'简要描述\',');
INSERT INTO `user19` VALUES ('  `main_image` varchar(100) DEFAULT \'\' COMMENT \'商品图片地址\',');
INSERT INTO `user19` VALUES ('  `sub_images` varchar(2000) DEFAULT \'\' COMMENT \'子图片列表\',');
INSERT INTO `user19` VALUES ('  `activity_id` bigint DEFAULT NULL COMMENT \'活动id\',');
INSERT INTO `user19` VALUES ('  `status` tinyint NOT NULL DEFAULT \'1\' COMMENT \'商品状态\',');
INSERT INTO `user19` VALUES ('  `price` decimal(20,2) NOT NULL DEFAULT \'0.00\' COMMENT \'商品单价\',');
INSERT INTO `user19` VALUES ('  `stock` int NOT NULL DEFAULT \'0\' COMMENT \'库存数\',');
INSERT INTO `user19` VALUES ('  `hot_flag` tinyint DEFAULT NULL COMMENT \'热门\',');
INSERT INTO `user19` VALUES ('  PRIMARY KEY (`id`) USING BTREE');
