INSERT INTO `user19` VALUES ('-- Table structure for user');
INSERT INTO `user19` VALUES ('-- ----------------------------');
INSERT INTO `user19` VALUES ('DROP TABLE IF EXISTS `user`;');
INSERT INTO `user19` VALUES ('CREATE TABLE `user` (');
INSERT INTO `user19` VALUES ('  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT \'主键\',');
INSERT INTO `user19` VALUES ('  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'创建时间\',');
INSERT INTO `user19` VALUES ('  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',');
INSERT INTO `user19` VALUES ('  `create_user` bigint NOT NULL DEFAULT \'0\' COMMENT \'创建人\',');
INSERT INTO `user19` VALUES ('  `update_user` bigint NOT NULL DEFAULT \'0\' COMMENT \'更新人\',');
INSERT INTO `user19` VALUES ('  `delete_flag` tinyint NOT NULL DEFAULT \'0\' COMMENT \'删除标志\',');
INSERT INTO `user19` VALUES ('  `status` tinyint NOT NULL DEFAULT \'1\' COMMENT \'启用标志\',');
INSERT INTO `user19` VALUES ('  `user_name` varchar(50) NOT NULL DEFAULT \'\' COMMENT \'用户名\',');
INSERT INTO `user19` VALUES ('  `email` varchar(50) NOT NULL DEFAULT \'\' COMMENT \'邮箱\',');
INSERT INTO `user19` VALUES ('  `phone` varchar(20) NOT NULL DEFAULT \'\' COMMENT \'手机号\',');
INSERT INTO `user19` VALUES ('  `password` varchar(100) NOT NULL DEFAULT \'\' COMMENT \'密码\',');
INSERT INTO `user19` VALUES ('  `type` varchar(255) NOT NULL COMMENT \'角色\',');
INSERT INTO `user19` VALUES ('  `nickname` varchar(255) NOT NULL COMMENT \'昵称\',');
INSERT INTO `user19` VALUES ('  `balance` decimal(20,2) unsigned DEFAULT NULL COMMENT \'余额\',');
INSERT INTO `user19` VALUES ('  PRIMARY KEY (`id`) USING BTREE,');
INSERT INTO `user19` VALUES ('  UNIQUE KEY `union_phone_idx` (`phone`) USING BTREE');
